// Some portions generated by Codex
package org.eclipse.rdf4j.sail.memory;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;

import java.math.BigDecimal;

import org.eclipse.rdf4j.model.Literal;
import org.eclipse.rdf4j.repository.sail.SailRepository;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.ValueSource;

class ExtensionAggregateRegressionTest {
	private static final String PREFIXES = """
			PREFIX agg: <http://rdf4j.org/aggregate#>
			PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
			""";

	@ParameterizedTest
	@ValueSource(strings = { "corr", "covarPop", "covarSamp", "approxQuantile" })
	void invalidNumericInputsLeaveOnlyTheAggregateUnbound(String aggregate) {
		SailRepository repository = new SailRepository(new MemoryStore());
		try (var connection = repository.getConnection();
				var result = connection.prepareTupleQuery(PREFIXES + "SELECT (agg:" + aggregate
						+ "(?x, 1) AS ?r) (COUNT(*) AS ?n) WHERE {VALUES ?x {'bad'^^xsd:double}}").evaluate()) {
			var row = result.next();
			assertFalse(row.hasBinding("r"));
			assertEquals("1", row.getValue("n").stringValue());
		} finally {
			repository.shutDown();
		}
	}

	@Test
	void medianRemainsExactThroughGroupingAndHaving() {
		SailRepository repository = new SailRepository(new MemoryStore());
		try (var connection = repository.getConnection();
				var result = connection.prepareTupleQuery(PREFIXES + """
						SELECT ?g (agg:median(?x) AS ?m) WHERE {
						  VALUES (?g ?x) {
						    (1 100000000000000000000000000000000000000)
						    (1 100000000000000000000000000000000000002)
						  }
						} GROUP BY ?g HAVING(COUNT(*) = 2)
						""").evaluate()) {
			var row = result.next();
			assertEquals(0, new BigDecimal("100000000000000000000000000000000000001")
					.compareTo(((Literal) row.getValue("m")).decimalValue()));
			assertFalse(result.hasNext());
		} finally {
			repository.shutDown();
		}
	}
}
